/* C evaluation fixture for the bounded polyhedral optimizer. */
long kernel(long seed){double a[1521],b[1521],c[1521];for(long i=0;i<39;i++)for(long j=0;j<39;j++){a[i*39+j]=(i+j+seed)&15;b[i*39+j]=(i*3+j)&7;c[i*39+j]=0;}for(long i=0;i<39;i++)for(long j=0;j<39;j++)for(long k=0;k<39;k++)c[i*39+j]+=a[i*39+k]*b[j*39+k];long sum=0;for(long i=0;i<39;i++)for(long j=0;j<39;j++)sum+=(long)c[i*39+j]*(i+j+1);return sum;}
